/* ──────────────────────────────────────────────────────────────────────────
 * Force-directed dependency graph (d3 v7), rendered into #dep-graph.
 *
 * Data: /assets/graph.json — {nodes:[{id}], links:[{source,target}]}, keyed by
 * repomgr repo name (generated by tools/gen_graph.py). Labels and colours are
 * resolved here from PROJECTS (projects.js), so identity lives in one place.
 *
 * Links point consumer → dependency; arrowheads sit on the dependency.
 * Adapted from https://observablehq.com/@d3/force-directed-graph/2
 * ────────────────────────────────────────────────────────────────────────── */

const GRAPH_R = 21; // node radius
const GRAPH_H = 460; // svg height

// repomgr repo name -> project record (for label + colour)
const REPO_TO_PROJECT = new Map(
  PROJECTS.filter((p) => p.repo).map((p) => [p.repo, p])
);

function nodeLabel(id) {
  return REPO_TO_PROJECT.get(id)?.name ?? id;
}

function nodeColor(id) {
  const p = REPO_TO_PROJECT.get(id);
  return p ? CATEGORIES[p.categories[0]].color : "#6b736b";
}

async function renderDependencyGraph(container) {
  const data = await fetch("/assets/graph.json").then((r) => r.json());
  const nodes = data.nodes.map((d) => ({ ...d }));
  const links = data.links.map((d) => ({ ...d }));

  let width = container.clientWidth || 760;
  const height = GRAPH_H;

  const simulation = d3
    .forceSimulation(nodes)
    .force("link", d3.forceLink(links).id((d) => d.id).distance(95).strength(0.5))
    .force("charge", d3.forceManyBody().strength(-520))
    .force("collide", d3.forceCollide(GRAPH_R + 14))
    .force("x", d3.forceX().strength(0.06))
    .force("y", d3.forceY().strength(0.09));

  const svg = d3
    .create("svg")
    .attr("viewBox", [-width / 2, -height / 2, width, height])
    .attr("width", "100%")
    .attr("height", height)
    .attr("font-family", "IBM Plex Mono, ui-monospace, monospace");

  // arrowhead marker
  svg
    .append("defs")
    .append("marker")
    .attr("id", "dep-arrow")
    .attr("viewBox", "0 0 10 10")
    .attr("refX", 9)
    .attr("refY", 5)
    .attr("markerWidth", 7)
    .attr("markerHeight", 7)
    .attr("orient", "auto-start-reverse")
    .append("path")
    .attr("d", "M0,0 L10,5 L0,10 z")
    .attr("fill", "#3a3f3a");

  const link = svg
    .append("g")
    .attr("stroke", "#2a2f2a")
    .attr("stroke-width", 1.5)
    .selectAll("line")
    .data(links)
    .join("line")
    .attr("marker-end", "url(#dep-arrow)");

  const node = svg
    .append("g")
    .selectAll("g")
    .data(nodes)
    .join("g")
    .attr("cursor", "grab")
    .call(drag(simulation));

  node
    .append("circle")
    .attr("r", GRAPH_R)
    .attr("fill", "#141714")
    .attr("stroke", (d) => nodeColor(d.id))
    .attr("stroke-width", 1.5);

  node
    .append("text")
    .text((d) => nodeLabel(d.id))
    .attr("text-anchor", "middle")
    .attr("dy", GRAPH_R + 15)
    .attr("font-size", 11)
    .attr("fill", (d) => nodeColor(d.id));

  // hover: emphasise a node and the links touching it
  node
    .on("mouseenter", (_, d) => {
      link
        .attr("stroke", (l) =>
          l.source.id === d.id || l.target.id === d.id ? nodeColor(d.id) : "#1f231f"
        )
        .attr("stroke-opacity", (l) =>
          l.source.id === d.id || l.target.id === d.id ? 1 : 0.3
        );
    })
    .on("mouseleave", () => {
      link.attr("stroke", "#2a2f2a").attr("stroke-opacity", 1);
    });

  // trim link end to the node edge so the arrowhead is visible
  function endpoint(a, b) {
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const dist = Math.hypot(dx, dy) || 1;
    return { x: b.x - (dx / dist) * (GRAPH_R + 6), y: b.y - (dy / dist) * (GRAPH_R + 6) };
  }

  simulation.on("tick", () => {
    link
      .attr("x1", (d) => d.source.x)
      .attr("y1", (d) => d.source.y)
      .attr("x2", (d) => endpoint(d.source, d.target).x)
      .attr("y2", (d) => endpoint(d.source, d.target).y);
    node.attr("transform", (d) => `translate(${d.x},${d.y})`);
  });

  container.replaceChildren(svg.node());

  // keep it responsive
  window.addEventListener("resize", () => {
    width = container.clientWidth || width;
    svg.attr("viewBox", [-width / 2, -height / 2, width, height]);
  });
}

function drag(simulation) {
  return d3
    .drag()
    .on("start", (event, d) => {
      if (!event.active) simulation.alphaTarget(0.3).restart();
      d.fx = d.x;
      d.fy = d.y;
    })
    .on("drag", (event, d) => {
      d.fx = event.x;
      d.fy = event.y;
    })
    .on("end", (event, d) => {
      if (!event.active) simulation.alphaTarget(0);
      d.fx = null;
      d.fy = null;
    });
}

document.addEventListener("DOMContentLoaded", () => {
  const container = document.getElementById("dep-graph");
  if (container && typeof d3 !== "undefined") {
    renderDependencyGraph(container).catch((err) =>
      console.error("dependency graph failed:", err)
    );
  }
});
